import type { Plugin, PluginContext } from "../../kernel/types";

// Minimal shape for an interval handle returned by the host resource manager.
type IntervalHandle = {
  clear?: () => void;
  stop?: () => void;
  dispose?: () => void;
  cancel?: () => void;
  close?: () => void;
};

/**
 * Start a timer through the host-managed ctx.resources.interval facility.
 * The exact signature is not pinned down in reachable docs, so we probe the
 * common shapes and return whatever handle the host gives us. The host tracks
 * resources created here so it can release them when the plugin stops.
 */
function startInterval(resources: any, fn: () => void, ms: number): any {
  const iv = resources?.interval;
  if (!iv) return null;
  try {
    if (typeof iv === "function") {
      // could be interval(fn, ms) or interval(ms, fn)
      return iv.call(resources, fn, ms) ?? iv.call(resources, ms, fn);
    }
    if (typeof iv.set === "function") return iv.set(fn, ms);
    if (typeof iv.start === "function") return iv.start(fn, ms);
    if (typeof iv.create === "function") return iv.create(fn, ms);
    if (typeof iv.every === "function") return iv.every(ms, fn);
    if (typeof iv.register === "function") return iv.register(fn, ms);
  } catch {
    // fall through: timer is best-effort, tool must still work
  }
  return null;
}

function stopInterval(handle: any): void {
  if (!handle) return;
  try {
    if (typeof handle === "function") {
      handle();
      return;
    }
    for (const m of ["clear", "stop", "dispose", "cancel", "close"] as const) {
      if (typeof handle[m] === "function") {
        handle[m]();
        return;
      }
    }
  } catch {
    // ignore
  }
}

const plugin: Plugin = {
  id: "temporary",
  name: "Temporary",
  version: "1.0.0",
  onLoad(ctx: PluginContext) {
    // Timer state, advanced by the host-managed interval resource.
    let ticks = 0;
    const handle = startInterval((ctx as any).resources, () => {
      ticks += 1;
    }, 1000);

    // Best-effort explicit cleanup hook if the host exposes one.
    const anyCtx = ctx as any;
    const cleanup = () => stopInterval(handle);
    if (typeof anyCtx.onUnload === "function") {
      anyCtx.onUnload(cleanup);
    } else if (typeof anyCtx.onDispose === "function") {
      anyCtx.onDispose(cleanup);
    }

    ctx.register({
      kind: "tool",
      tool: {
        name: "lifetime_value",
        version: "1.0.0",
        description: "Returns the constant lifetime value 9.",
        permissions: [],
        sideEffect: "none",
        parameters: {
          type: "object",
          properties: {},
          additionalProperties: false,
        },
        outputSchema: {
          type: "object",
          properties: {
            ok: { type: "boolean" },
            data: {
              type: "object",
              properties: {
                value: { type: "number" },
                ticks: { type: "number" },
              },
              required: ["value"],
              additionalProperties: true,
            },
          },
          required: ["ok", "data"],
        },
        async handler(_args: unknown, _tctx: unknown) {
          // Pure computation: constant value, no I/O.
          return { ok: true, data: { value: 9, ticks } };
        },
      },
    });
  },
};

export default plugin;

